import React, { useState } from 'react';
import { Mail, MessageSquare, RefreshCw, Eye, Copy, Check, X, User } from 'lucide-react';
import PageHeader from '../components/PageHeader';
import DataTable from '../components/DataTable';

// ============================================================================
// QUERIES ADMIN MANAGEMENT PAGE (/admin/queries)
// ============================================================================
// Read-only inquiries table from live Supabase table: public.queries
// Limited to Administrator role only.
//
// Schema:
// - id: bigint generated by default as identity not null (Primary Key)
// - name: character varying null
// - email: character varying null
// - subject: character varying null
// - message: character varying null
// ============================================================================

export default function Queries({
  queries = [],
  isLoading = false,
  onRefresh
}) {
  const [selectedQuery, setSelectedQuery] = useState(null);
  const [copiedEmail, setCopiedEmail] = useState(null);

  const handleCopyEmail = (email, e) => {
    e.stopPropagation();
    navigator.clipboard.writeText(email);
    setCopiedEmail(email);
    setTimeout(() => setCopiedEmail(null), 2000);
  };

  const columns = [
    {
      key: 'id',
      label: 'ID',
      render: (row) => (
        <span
          style={{
            fontFamily: 'monospace',
            fontWeight: 700,
            fontSize: '0.8rem',
            color: 'var(--admin-blue-primary)',
            backgroundColor: 'var(--admin-blue-light)',
            padding: '0.2rem 0.5rem',
            borderRadius: '4px',
            border: '1px solid var(--admin-border-blue)'
          }}
        >
          #{row.id}
        </span>
      )
    },
    {
      key: 'name',
      label: 'Sender Name',
      render: (row) => (
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <div
            style={{
              width: '28px',
              height: '28px',
              borderRadius: '50%',
              backgroundColor: 'rgba(37, 99, 235, 0.1)',
              color: 'var(--admin-blue-primary)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontWeight: 700,
              fontSize: '0.75rem',
              flexShrink: 0
            }}
          >
            {row.name ? row.name.charAt(0).toUpperCase() : <User size={14} />}
          </div>
          <span style={{ fontWeight: 600, color: 'var(--admin-text-title)' }}>
            {row.name || 'Anonymous'}
          </span>
        </div>
      )
    },
    {
      key: 'email',
      label: 'Email Address',
      render: (row) => (
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
          <Mail size={13} color="var(--admin-sky-blue)" />
          {row.email ? (
            <a
              href={`mailto:${row.email}`}
              style={{
                color: 'var(--admin-blue-primary)',
                textDecoration: 'none',
                fontSize: '0.82rem'
              }}
              onClick={(e) => e.stopPropagation()}
            >
              {row.email}
            </a>
          ) : (
            <span style={{ color: 'var(--admin-text-faint)', fontSize: '0.82rem' }}>None</span>
          )}
          {row.email && (
            <button
              type="button"
              className="admin-btn-icon"
              style={{ width: '22px', height: '22px', padding: 0 }}
              title="Copy Email"
              onClick={(e) => handleCopyEmail(row.email, e)}
            >
              {copiedEmail === row.email ? <Check size={11} color="#16A34A" /> : <Copy size={11} />}
            </button>
          )}
        </div>
      )
    },
    {
      key: 'subject',
      label: 'Subject',
      render: (row) => (
        <span
          style={{
            fontWeight: 600,
            fontSize: '0.82rem',
            color: 'var(--admin-text-main)',
            maxWidth: '180px',
            display: 'inline-block',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap'
          }}
          title={row.subject}
        >
          {row.subject || 'General Inquiry'}
        </span>
      )
    },
    {
      key: 'message',
      label: 'Message Inquiry',
      render: (row) => (
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', maxWidth: '300px' }}>
          <span
            style={{
              fontSize: '0.82rem',
              color: 'var(--admin-text-muted)',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap',
              flex: 1
            }}
            title={row.message}
          >
            {row.message || '(Empty message)'}
          </span>
          <button
            type="button"
            className="admin-btn admin-btn-secondary admin-btn-sm"
            style={{ padding: '0.2rem 0.5rem', fontSize: '0.72rem', flexShrink: 0 }}
            onClick={() => setSelectedQuery(row)}
            title="View complete message"
          >
            <Eye size={12} />
            <span>View</span>
          </button>
        </div>
      )
    }
  ];

  return (
    <div className="admin-page-container">
      {/* Page Header */}
      <PageHeader
        title="Public Queries"
        subtitle={`Read-only inquiries submitted by visitors from the public website (${queries.length} total queries)`}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
          {onRefresh && (
            <button
              type="button"
              className="admin-btn admin-btn-secondary"
              onClick={onRefresh}
              disabled={isLoading}
              title="Sync queries with Supabase"
            >
              <RefreshCw size={14} className={isLoading ? 'admin-spinner' : ''} />
              <span>{isLoading ? 'Syncing...' : 'Sync'}</span>
            </button>
          )}
        </div>
      </PageHeader>

      {/* Read-Only Queries Table */}
      <DataTable
        columns={columns}
        data={queries}
        searchKey={(item, query) =>
          (item.name || '').toLowerCase().includes(query) ||
          (item.email || '').toLowerCase().includes(query) ||
          (item.subject || '').toLowerCase().includes(query) ||
          (item.message || '').toLowerCase().includes(query)
        }
        searchPlaceholder="Search queries by name, email, subject, or message content..."
        emptyMessage="No queries found in the database."
      />

      {/* View Query Details Modal */}
      {selectedQuery && (
        <div className="admin-modal-backdrop" onClick={() => setSelectedQuery(null)}>
          <div
            className="admin-modal-container"
            style={{ maxWidth: '580px' }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="admin-modal-header">
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                <div
                  style={{
                    width: '32px',
                    height: '32px',
                    borderRadius: '8px',
                    backgroundColor: 'rgba(37, 99, 235, 0.12)',
                    color: 'var(--admin-blue-primary)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center'
                  }}
                >
                  <MessageSquare size={16} />
                </div>
                <h3 className="admin-modal-title" style={{ margin: 0 }}>
                  Inquiry Details #{selectedQuery.id}
                </h3>
              </div>
              <button
                type="button"
                className="admin-btn-icon"
                onClick={() => setSelectedQuery(null)}
                aria-label="Close query modal"
              >
                <X size={18} />
              </button>
            </div>

            <div className="admin-modal-body" style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {/* Sender & Email */}
              <div
                style={{
                  display: 'grid',
                  gridTemplateColumns: '1fr 1fr',
                  gap: '0.75rem',
                  backgroundColor: 'var(--admin-bg-table-header)',
                  padding: '0.85rem 1rem',
                  borderRadius: '8px',
                  border: '1px solid var(--admin-border-subtle)'
                }}
              >
                <div>
                  <div style={{ fontSize: '0.72rem', fontWeight: 700, color: 'var(--admin-text-faint)', textTransform: 'uppercase' }}>
                    Sender Name
                  </div>
                  <div style={{ fontSize: '0.9rem', fontWeight: 600, color: 'var(--admin-text-title)', marginTop: '0.2rem' }}>
                    {selectedQuery.name || 'Anonymous'}
                  </div>
                </div>

                <div>
                  <div style={{ fontSize: '0.72rem', fontWeight: 700, color: 'var(--admin-text-faint)', textTransform: 'uppercase' }}>
                    Email Address
                  </div>
                  <div style={{ fontSize: '0.9rem', marginTop: '0.2rem' }}>
                    {selectedQuery.email ? (
                      <a
                        href={`mailto:${selectedQuery.email}`}
                        style={{ color: 'var(--admin-blue-primary)', textDecoration: 'none', fontWeight: 600 }}
                      >
                        {selectedQuery.email}
                      </a>
                    ) : (
                      <span style={{ color: 'var(--admin-text-muted)' }}>Not provided</span>
                    )}
                  </div>
                </div>
              </div>

              {/* Subject */}
              <div>
                <div style={{ fontSize: '0.72rem', fontWeight: 700, color: 'var(--admin-text-faint)', textTransform: 'uppercase', marginBottom: '0.25rem' }}>
                  Subject
                </div>
                <div
                  style={{
                    fontSize: '0.92rem',
                    fontWeight: 600,
                    color: 'var(--admin-text-title)',
                    padding: '0.6rem 0.85rem',
                    backgroundColor: 'var(--admin-surface)',
                    border: '1px solid var(--admin-border-subtle)',
                    borderRadius: '6px'
                  }}
                >
                  {selectedQuery.subject || 'General Inquiry'}
                </div>
              </div>

              {/* Message */}
              <div>
                <div style={{ fontSize: '0.72rem', fontWeight: 700, color: 'var(--admin-text-faint)', textTransform: 'uppercase', marginBottom: '0.25rem' }}>
                  Full Message
                </div>
                <div
                  style={{
                    fontSize: '0.88rem',
                    lineHeight: 1.6,
                    color: 'var(--admin-text-main)',
                    padding: '0.85rem 1rem',
                    backgroundColor: 'var(--admin-surface)',
                    border: '1px solid var(--admin-border-subtle)',
                    borderRadius: '6px',
                    whiteSpace: 'pre-wrap',
                    minHeight: '120px',
                    maxHeight: '260px',
                    overflowY: 'auto'
                  }}
                >
                  {selectedQuery.message || '(Empty message)'}
                </div>
              </div>
            </div>

            <div className="admin-modal-footer" style={{ margin: '1rem -1.5rem -1.5rem -1.5rem', justifyContent: 'space-between' }}>
              <div style={{ fontSize: '0.75rem', color: 'var(--admin-text-faint)' }}>
                Read-only CMS View &bull; public.queries
              </div>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                {selectedQuery.email && (
                  <a
                    href={`mailto:${selectedQuery.email}?subject=Re: ${encodeURIComponent(selectedQuery.subject || 'Technospark Inquiry')}`}
                    className="admin-btn admin-btn-primary admin-btn-sm"
                    style={{ textDecoration: 'none' }}
                  >
                    <Mail size={13} />
                    <span>Reply via Email</span>
                  </a>
                )}
                <button
                  type="button"
                  className="admin-btn admin-btn-secondary admin-btn-sm"
                  onClick={() => setSelectedQuery(null)}
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

